head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.vIsurCd = "";
scwin.vLIST_STAT_CD = "Y";
// 호출메뉴ID를 식별하기 위한 함수사용
// 세션정보를 얻기위한 함수사용
// 상장관련공통함수
// jackal_11.05.12

scwin.fr_SecuGrpId = SECUGRP_ID_EN; // mid 부모프레임으로 부터 받은 menu id로 증권그룹id를 반환하는 함수 호출, 법인선택팝업에서 fr_SecuGrpId 변수를 참조.
scwin.fr_MktId = $c.lce.fn_getMktId(); // 시장구분코드(유가, 코스닥) 전체), 기준은 로그인 사용자의 부서 소속을 기준으로 한다.
scwin.fn_GetPar, scwin.fn_SetPar;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        $c.libRoundPanel.PanelToGroupBox(pan_Cnd);
        rdo_ISUR_CD_1.setValue("1");
        scwin.changeRadioBtn(1);
        await scwin.getIsurcode();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08041.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name img_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_Search_onclick = async function() {
    try {
        if (rdo_ISUR_CD_1.getValue() === "1") {
            if (txb_ISU_CD.getValue() === "") {
                await $c.win.alert($c.stf.getMessageParam("MSG-0015", ""));
                return true;
            }
        }
        await scwin.search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08041.img_Search_onclick" });
    }
};

/**
 * @method
 * @name dts_OnLoadError
 * @description dts 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_OnLoadError = async function() {
    try {
        await $c.win.alert(dts);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08041.dts_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_OnLoadCompleted
 * @description dts 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_OnLoadCompleted = function(rowcount) {
    try {
        // FillGridHeaderTotalCnt(rowcount, panel_page);
        txb_TotCnt.setValue("총건수 : " + rowcount);
        dts.setRowPosition(rowcount, 0);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF08041.dts_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name img_Excel_onclick
 * @description 「엑셀다운로드」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_Excel_onclick = async function() {
    try {
        if (dts.getRowCount() > 0) {
            $c.stf.doLogSave("ULDSTF08041.xml", SCREN_PROCS_TP_CD_07);
            $c.data.downloadGridViewExcel(grd_List, {fileName: $c.lce.fn_getSecuGrpNm(scwin.fr_SecuGrpId) + "매매거래정지내역", type: "8"});
        } else {
            await $c.win.alert(NO_EXCEL_DATA);
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08041.img_Excel_onclick" });
    }
};

/**
 * @method
 * @name img_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_Close_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08041.img_Close_onclick" });
    }
};

/**
 * @method
 * @name btn_iSU_CD_onclick
 * @description btn_iSU_CD 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_iSU_CD_onclick = function() {
    try {
        scwin.fn_GetPar = scwin.getParIsur;
        scwin.fn_SetPar = scwin.setParIsur;
        // fn_PopFindIsu(fr_SecuGrpId);
        // fn_PopFindIsuAll(fr_SecuGrpId);        // jackal_11.05.12
        $c.lce.fn_PopFindEtnIsuAll(scwin.fr_SecuGrpId);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF08041.btn_iSU_CD_onclick" });
    }
};

/**
 * @method
 * @name img_Regist_onclick
 * @description 「신규」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_Regist_onclick = async function() {
    try {
        if (rdo_ISUR_CD_1.getValue() === "1") {
            if (txb_ISU_CD.getValue() === "") {
                await $c.win.alert($c.stf.getMessageParam("MSG-0015", ""));
                return true;
            }
            if (cmb_RegistTyp.getSelectedIndex() === 0) {
                await $c.win.alert($c.stf.getMessageParam("MSG-0014", ""));
                cmb_RegistTyp.focus();
                return true;
            }
            if (cmb_RegistTyp.BindColVal === "1") {
                await $c.win.alert("매매거래정지 지정 세부화면에서 해제 해주시기 바랍니다.");
                return true;
            }
        } else {
            if (cmb_RegistTyp.getSelectedIndex() === 0) {
                await $c.win.alert($c.stf.getMessageParam("MSG-0014", ""));
                cmb_RegistTyp.focus();
                return true;
            }
        }
        scwin.fn_GetPar = scwin.getParNew;
        scwin.fn_SetPar = undefined;
        if (rdo_ISUR_CD_2.getValue() === "1") {
            await scwin.newCreateFrame(cmb_RegistTyp.BindColVal, "");
        } else {
            await scwin.newpreCreateFrame(cmb_RegistTyp.BindColVal, "");
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08041.img_Regist_onclick" });
    }
};

/**
 * @method
 * @name grd_List_OnDblClick
 * @description grd_List 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_List_OnDblClick = async function(row, colid) {
    try {
        // jackal_11.05.12 삭제종목인 경우 팝업 금지
        if (rdo_ISUR_CD_1.getValue() === "1") {
            if (scwin.vLIST_STAT_CD === "D") {
                return true;
            }
        }
        scwin.vIsurCd = dts.getCellData(dts.getRowPosition(), "ISUR_CD");
        scwin.fn_GetPar = scwin.getParUpdate; // 수정시 인수를 넘기는 function을 fn_GetPar란 변수에 할당, (팝업화면에서 참조하는 변수명이 fn_GetPar임)
        scwin.fn_SetPar = undefined;

        // 거래정지지정및해제구분코드 값 넘겨야함
        await scwin.newpreCreateFrame(dts.getCellData(dts.getRowPosition(), "HALT_DESNRELS_TP_CD"), dts.getCellData(dts.getRowPosition(), "TRD_HALT_STRT_DD"));
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08041.grd_List_OnDblClick" });
    }
};

/**
 * @method
 * @name rdo_ISUR_CD_1_onclick
 * @description rdo_ISUR_CD_1 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.rdo_ISUR_CD_1_onclick = function() {
    try {
        // rdo_ISUR_CD_2.CodeValue ="2";
        scwin.changeRadioBtn(1);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF08041.rdo_ISUR_CD_1_onclick" });
    }
};

/**
 * @method
 * @name rdo_ISUR_CD_2_onclick
 * @description rdo_ISUR_CD_2 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.rdo_ISUR_CD_2_onclick = async function() {
    try {
        // rdo_ISUR_CD_1.CodeValue ="2";
        scwin.changeRadioBtn(2);
        await scwin.search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08041.rdo_ISUR_CD_2_onclick" });
    }
};

/**
 * @method
 * @name cmb_ISUR_CD_onselchange
 * @description cmb_ISUR_CD onselchange 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.cmb_ISUR_CD_onselchange = async function() {
    try {
        scwin.changeRadioBtn(2);
        // if( rdo_ISUR_CD_2.CodeValue == "1" && cmb_ISUR_CD.index != 0 ) {
        await scwin.search();
        // }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08041.cmb_ISUR_CD_onselchange" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name search
 * @description jackal_11.05.12 상장종목 여부 체크 추가
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function() {
    url += "&SCREN_ID=" + "ULDSTF08041.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    if (rdo_ISUR_CD_1.getValue() === "1") {
        url += "&DIV_IDX=" + DIV_IDX_ETN_LIST_ISU + "&TRS_IDX=" + TRS_IDX_SELECT + "&ISU_CD=" + txb_ISU_CD.getValue();
    } else if (rdo_ISUR_CD_2.getValue() === "1") {
        if (cmb_ISUR_CD.getSelectedIndex() === 0) {
            url += "&DIV_IDX=" + DIV_IDX_ETN_LIST_ALL + "&TRS_IDX=" + TRS_IDX_SELECT + "&GUBUN_CD=ETN";
        } else {
            url += "&DIV_IDX=" + DIV_IDX_ETN_LIST_CORP + "&TRS_IDX=" + TRS_IDX_SELECT + "&ISUR_CD=" + cmb_ISUR_CD.BindColVal + "&GUBUN_CD=ETN";
        }
    }
    // alert(url);
    const sbmOptions = {
        id : "sbm_dts",
        action : "/etn/EtnMktAct.do",
        ref : "",
        target : "dts=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name getIsurcode
 * @description etn발행사
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.getIsurcode = async function() {
    // etn발행사
    const sbmOptions = {
        id : "sbm_dts_EtnInst",
        action : "/etn/EtnCodeAct.do",
        ref : "",
        target : "dts_EtnInst=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name popupCallback
 * @description browserPopup 팝업의 callback 함수. 부모창에서 팝업 결과 값을 처리한다.
 * @param {*} arg 팝업에서 전달받은 값
 * @returns {void}
 * @hidden N
 */
scwin.popupCallback = function (arg) {
    // TO-DO : arg 값 확인 후 업무 로직 추가
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name getParIsur
 * @description dialog 호출용 함수 예비심사청구제출기관 호출관련
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.getParIsur = function(arrPar) {
    // 넘길 인수를 지정하는 펑션
    arrPar[0] = ""; // 코드값을 포함할 컨트롤
    arrPar[1] = txb_ISU_NM.getValue(); // 명칭값을 포함할 컨트롤
    arrPar[2] = scwin.fr_SecuGrpId; // 명칭값을 포함할 컨트롤

    return arrPar.length;
};

/**
 * @method
 * @name setParIsur
 * @description set Par Isur 처리
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setParIsur = async function(arrPar) {
    const dbClickYn = arrPar[0].DBCLICKYN;
    if (dbClickYn === "Y") {
        scwin.changeRadioBtn(1);
        txb_ISU_CD.setValue(arrPar[0].ISU_CD);
        // txb_ISU_NM.value = arrPar[0].ISU_KOR_NM;
        txb_ISU_NM.setValue(arrPar[0].ISU_KOR_ABBRV);
        scwin.vIsurCd = arrPar[0].ISUR_CD;
    }
    await scwin.search();
    // jackal_11.05.12
    // 삭제 종목인 경우 모든 버튼 discable
    scwin.vLIST_STAT_CD = arrPar[0].LIST_STAT_CD;
    if (scwin.vLIST_STAT_CD === "D") {
        img_Regist.setDisabled(true);
        img_Regist.setBackgroundImage("../img/btn_new_d.gif");
    } else {
        img_Regist.setDisabled(false);
        img_Regist.setBackgroundImage("../img/btn_new.gif");
    }
};

/**
 * @method
 * @name getParUpdate
 * @description 넘길 인수를 지정하는 펑션
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.getParUpdate = function(arrPar) {
    // 넘길 인수를 지정하는 펑션
    if (rdo_ISUR_CD_1.getValue() === "1") {
        arrPar[0] = scwin.vIsurCd; // 발행기관코드값
        arrPar[1] = txb_ISU_NM.getValue(); // 종목명
        arrPar[6] = txb_ISU_CD.getValue(); // 종목코드값
        arrPar[7] = "1"; // 선택 구분(1:종목, 2:발행회사, 3:전체)

    } else if (rdo_ISUR_CD_2.getValue() === "1") {
        if (cmb_ISUR_CD.getSelectedIndex() === 0) {
            arrPar[0] = scwin.vIsurCd; // 발행기관코드값
            arrPar[1] = dts.getCellData(dts.getRowPosition(), "COM_NM"); // 발행기관명
            arrPar[6] = ""; // 종목코드값
            arrPar[7] = "3"; // 선택 구분(1:종목, 2:발행회사, 3:전체)

        } else {
            arrPar[0] = scwin.vIsurCd; // 발행기관코드값
            arrPar[1] = dts.getCellData(dts.getRowPosition(), "COM_NM"); // 발행기관명
            // arrPar[1] = cmb_ISUR_CD.Text; // 발행기관명
            arrPar[6] = ""; // 종목코드값
            arrPar[7] = "2"; // 선택 구분(1:종목, 2:발행회사, 3:전체)

        }
    }
    arrPar[2] = scwin.fr_SecuGrpId; // 증권그룹구분
    arrPar[3] = scwin.fr_MktId; // 시장구분
    arrPar[4] = dts.getCellData(dts.getRowPosition(), "bz_procs_no"); // 업무처리번호
    arrPar[5] = dts.getCellData(dts.getRowPosition(), "HALT_DESNRELS_TP_CD"); // 거래정지지정및해제구분코드

    return arrPar.length;
};

/**
 * @method
 * @name getParNew
 * @description 신규생성시 지정하는 평션
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.getParNew = function(arrPar) {
    // 신규생성시 지정하는 평션
    if (rdo_ISUR_CD_1.getValue() === "1") {
        arrPar[0] = scwin.vIsurCd; // 발행기관코드값
        arrPar[1] = txb_ISU_NM.getValue(); // 발행기관명
        arrPar[6] = txb_ISU_CD.getValue(); // 종목코드값
        arrPar[7] = "1"; // 선택 구분(1:종목, 2:발행회사, 3:전체)

    } else if (rdo_ISUR_CD_2.getValue() === "1") {
        if (cmb_ISUR_CD.getSelectedIndex() === 0) {
            arrPar[0] = ""; // 발행기관코드값
            arrPar[1] = ""; // 발행기관명
            arrPar[6] = ""; // 종목코드값
            arrPar[7] = "3"; // 선택 구분(1:종목, 2:발행회사, 3:전체)

        } else {
            arrPar[0] = cmb_ISUR_CD.BindColVal; // 발행기관코드값
            arrPar[1] = cmb_ISUR_CD.getText(); // 발행기관명
            arrPar[6] = ""; // 종목코드값
            arrPar[7] = "2"; // 선택 구분(1:종목, 2:발행회사, 3:전체)

        }
    }
    arrPar[2] = scwin.fr_SecuGrpId; // 증권그룹구분
    arrPar[3] = scwin.fr_MktId; // 시장구분
    arrPar[4] = ""; // 신규작성시 업무처리번호는 없다.
    arrPar[5] = cmb_RegistTyp.BindColVal; // 거래정지지정및해제구분코드

};

/**
 * @method
 * @name newCreateFrame
 * @description new Create Frame 처리
 * @param {*} arg arg
 * @param {String} startDd startDd
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.newCreateFrame = async function(arg, startDd) {
    /*
    0:지정, 1:해제, 2:지정및해제(유), 3:지정->해제
     */
    switch (arg) {
        case "0":
            const options = {
                id: "ULDSTF08043_new",
                title: $c.lce.fn_getSecuGrpNm(scwin.fr_SecuGrpId) + " 매매거래정지 지정",
                type: "browserPopup",
                width: "745px",
                height: "540px",
                callbackFn: "scwin.popupCallback"
            };

            $c.win.openPopup("../etn/ULDSTF08043_new.gfm", options);
            break;
        case "1":
            const options2 = {
                id: "ULDSTF08044_new",
                title: $c.lce.fn_getSecuGrpNm(scwin.fr_SecuGrpId) + " 매매거래정지 해제",
                type: "browserPopup",
                width: "745px",
                height: "650px",
                callbackFn: "scwin.popupCallback"
            };

            $c.win.openPopup("../etn/ULDSTF08044_new.gfm", options2);
            break;
        case "2":
            const options3 = {
                id: "ULDSTF08042_new",
                title: $c.lce.fn_getSecuGrpNm(scwin.fr_SecuGrpId) + " 매매거래정지 지정 및 해제",
                type: "browserPopup",
                width: "745px",
                height: "570px",
                callbackFn: "scwin.popupCallback"
            };

            $c.win.openPopup("../etn/ULDSTF08042_new.gfm", options3);
            break;
    }
    cmb_RegistTyp.setSelectedIndex(0);
};

/**
 * @method
 * @name newpreCreateFrame
 * @description newpre Create Frame 처리
 * @param {*} arg arg
 * @param {String} startDd startDd
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.newpreCreateFrame = async function(arg, startDd) {
    if (arg === "1" && startDd !== "") arg = "3";
    // alert(arg) ;
    /*
    0:지정, 1:해제, 2:지정및해제(유), 3:지정->해제
     */
    switch (arg) {
        case "0":
            const options = {
