    // fn_search() ; // 다이얼로그 창이 닫히면 조회를 보낸다.

    cmb_RegistTyp.setSelectedIndex(0);
};

/**
 * @method
 * @name changeRadioBtn
 * @description change Radio Btn 처리
 * @param {Number} idx idx
 * @returns {void}
 * @hidden N
 */
scwin.changeRadioBtn = function(idx) {
    if (idx === "1") {
        cmb_ISUR_CD.setSelectedIndex(0);
        rdo_ISUR_CD_1.setValue("1");
        rdo_ISUR_CD_2.setValue("2");

        // cmb_RegistTyp.DeleteData(3);  //유가이면 재상장구분코드 삭제

    } else if (idx === "2") {
        txb_ISU_CD.setValue("");
        txb_ISU_NM.setValue("");
        rdo_ISUR_CD_1.setValue("2");
        rdo_ISUR_CD_2.setValue("1");

        // cmb_RegistTyp.InsertData("1^매매거래정지 해제");

    }
};
